import random, subprocess, sys, tempfile
from pathlib import Path
REFERENCE="# External reference: statistics page /practice/28202/\n# Accepted submission: 52825193\n# Source: http://cs101.openjudge.cn/practice/solution/52825193/\n# License: not declared on the submission page; no license is inferred.\n\nimport sys\n\n# 增加递归深度限制，防止大样本下发生溢出\nsys.setrecursionlimit(2000)\n\ndef solve():\n    # 使用快速输入读取所有数据\n    input_data = sys.stdin.read().split()\n    if not input_data:\n        return\n\n    T = int(input_data[0])\n    idx = 1\n    out = []\n\n    for _ in range(T):\n        N = int(input_data[idx])\n        S = input_data[idx+1]\n        idx += 2\n\n        def get_min_ops(L, R, char_val):\n            # 基准情况：长度为 1\n            if L == R:\n                target_char = chr(97 + char_val)  # 97 是 'a' 的 ASCII 码\n                return 0 if S[L] == target_char else 1\n\n            M = (L + R) // 2\n            target_char = chr(97 + char_val)\n\n            # 选择一：左半部分全为 target_char，右半部分递归\n            cnt_left = S.count(target_char, L, M + 1)\n            cost_left = (M - L + 1) - cnt_left\n            opt1 = cost_left + get_min_ops(M + 1, R, char_val + 1)\n\n            # 选择二：左半部分递归，右半部分全为 target_char\n            cnt_right = S.count(target_char, M + 1, R + 1)\n            cost_right = (R - M) - cnt_right\n            opt2 = get_min_ops(L, M, char_val + 1) + cost_right\n\n            return opt1 if opt1 < opt2 else opt2\n\n        # 从 1-阶好串开始，对应字符 'a' (char_val = 0)\n        ans = get_min_ops(0, N - 1, 0)\n        out.append(str(ans))\n\n    print('\\n'.join(out))\n\nif __name__ == '__main__':\n    solve()"
SAMPLE='6\n8\nbbdcaaaa\n8\nasdfghjk\n8\nceaaaabb\n8\nbbaaddcc\n1\nz\n2\nac\n'
EXTRA_CASE='1\n131072\\n'
GENERATOR_NAME='g28202'
def g28202(r):
    t = r.randint(1, 8); rows = [str(t)]
    for _ in range(t):
        n = r.choice([1, 2, 4, 8, 16, 32, 64, 128])
        rows += [str(n), "".join(r.choice("abcdefghijklmnopqrstuvwxyz") for _ in range(n))]
    return "\n".join(rows) + "\n"

def run(text):
    with tempfile.TemporaryDirectory(prefix='producecase-') as d:
        p=Path(d)/'main.py'; p.write_text(REFERENCE)
        x=subprocess.run([sys.executable,str(p)],input=text,text=True,capture_output=True,timeout=90)
        if x.returncode: raise SystemExit(x.stderr)
        return x.stdout
def scale_case(): return EXTRA_CASE
def main():
    d=Path('data'); d.mkdir(exist_ok=True)
    extra=scale_case(); cases=[SAMPLE]+([extra] if extra else [])+[globals()[GENERATOR_NAME](random.Random(s)) for s in range(1,21)]
    for i,c in enumerate(cases): (d/f'{i}.in').write_text(c); (d/f'{i}.out').write_text(run(c))
if __name__=='__main__': main()
